  "body": " This active code uses the print functions for Complex objects. Feel free to modify the code and experiment around!   #include <iostream> #include <cmath> class Complex { double real, imag; double mag, theta; bool cartesian, polar; public: Complex(); Complex(double r, double i); void calculateCartesian(); double getReal(); double getImag(); void calculatePolar(); double getMag(); double getTheta(); void printCartesian(); void printPolar(); }; int main() { Complex c1 (2.0, 3.0); c1.printCartesian(); c1.printPolar(); }  Complex::Complex() { cartesian = false; polar = false; } Complex::Complex(double r, double i) { real = r; imag = i; cartesian = true; polar = false; } void Complex::calculateCartesian() { real = mag * cos (theta); imag = mag * sin (theta); cartesian = true; } double Complex::getReal() { if (cartesian == false) calculateCartesian(); return real; } double Complex::getImag() { if (cartesian == false) calculateCartesian(); return imag; } void Complex::calculatePolar() { mag = std::sqrt(std::pow(real, 2) + std::pow(imag, 2)); theta = atan(imag \/ real); polar = true; } double Complex::getMag() { if (polar == false) { calculatePolar(); } return mag; } double Complex::getTheta() { if (polar == false) { calculatePolar(); } return theta; } void Complex::printCartesian() { std::cout << getReal() << \" + \" << getImag() << \"i\" << std::endl; } void Complex::printPolar() { std::cout << getMag() << \" e^ \" << getTheta() << \"i\" << std::endl; }   "
